```python
def find_mst(n):
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            edges.append((i, j, (i|j) - min(i, j)))
    edges.sort()
    mst = []
    parent = list(range(n))
    for (u, v, w) in edges:
        if parent[u] != parent[v]:
            mst.append((u, v, w))
            parent[v] = u
            n -= 1
            if n == 1:
                break
    return sum(w for (u, v, w) in mst)
n = int(input())
print(find_mst(n))
```

