```python
import string

def min_hamming_distance(s, t):
    n = len(s)
    sc_dict = {c: s.count(c) for c in string.ascii_lowercase}
    tc_dict = {c: t.count(c) for c in string.ascii_lowercase}

    for c in string.ascii_lowercase:
        if sc_dict[c] == tc_dict[c]:
            continue
        if abs(sc_dict[c] - tc_dict[c]) == min(abs(sc_dict[d] - tc_dict[d]) for d in string.ascii_lowercase):
            i = s.find(c) + 1
            j = t.find(c) + 1
            return min_hamming_distance(s[:i] + s[j] + s[i:j] + s[j-1] + s[i] + s[j+1:]), (i, j)
    return n, -1, -1

# Test cases
print(min_hamming_distance('pergament', 'permanent'))
print(min_hamming_distance('wookie', 'cookie'))
print(min_hamming_distance('petr', 'egor'))
print(min_hamming_distance('double', 'bundle'))```

