# Function to find m-free matrix
def find_mfree_matrix(x, m):
    n = int(math.sqrt(x) + 1)
    for d in range(1, n):
        if x % d == 0:
            s = x // d
            n = (s + d) // 2
            if int(n) != n:
                continue
            m = n // s
            if m > 0 and n**2 - m**2 == x:
                return n, m
    return -1

# Main function
if __name__ == '__main__':
    n_m = []
    t = int(input())
    for _ in range(t):
        x = int(input())
        n, m = find_mfree_matrix(x, m)
        n_m.append((n, m))
    for n, m in n_m:
        print(n, m)
