m = 301000
s = [0] * m
ss = [0] * m

def update(i, l, r, k, v):
    if r < k or l > k:
        return
    if l == k and r == k:
        s[i] += v
        ss[i] += v * (k - 1)
        return
    mid = (l + r) // 2
    update(2 * i, l, mid, k, v)
    update(2 * i + 1, mid + 1, r, k, v)

def query(i, l, r, k):
    if r < k or l > k:
        return 0
    if l == k and r == k:
        return s[i]
    mid = (l + r) // 2
    return query(2 * i, l, mid, k) + query(2 * i + 1, mid + 1, r, k)

def calc(k):
    q = 0
    for i in range(1, k + 1):
        q += query(1, 1, m, i)
    return q

