def wtf(i, k , n):
    if i >= n - k:
        return i
    elif (n-k) % 2 == 0:
        if i % 2 == 0:
            return i + 1
        elif i == 1:
            return 1
        else:
            return i - 1
    else:
        if i % 2 == 0:
            return i - 1
        else:
            return i + 1
