import time
import sys
from math import sqrt

# Read input
n = int(input())
a = list(map(int, input().split()))

# Find divisors of a[0]
sq = int(sqrt(a[0]))+2
s = set()
for box in range(1, sq):
    if a[0] % box == 0:
        s.add(a[0] // box)
        s.add(a[0] // box - 1)
    else:
        s.add(a[0] // box)

# Check if difference between sizes of any two sets is greater than 1
for balls in range(1, sq):
    if a[0] % balls <= a[0] // balls:
        s.add(balls)

# Calculate minimum number of sets
sizes = sorted(s, reverse=True)
min_sets = len(sizes)
for size in sizes:
    ans = 0
    for x in a:
        if x / size >= x % size:
            ans += (x+size) // (size+1)
        else:
            break
    else:
        min_sets = ans

print(min_sets)```

