def calc_shortest(D, s1, s2):
    if s1 == s2:
        return 0
    elif s1 < s2:
        path1 = sum(D[s1-1:s2-1])
    else:
        path1 = sum(D[s2-1:s1-1])
    path2 = sum(D)-path1
    if path1 < path2:
        return path1
    else:
        return path2
