  last=0
  flag=False
  for pos in range(n):
    if flag==False:
      if board[i][pos]=='B':
        first=pos
        flag=True
    else:
      if board[i][pos]=='B':
        last=pos
  if first==-1:
    whites+=1
    continue
  if last==0:
