class InputHandlerObject(object):
    inputs = []
    def getInput(self, n = 0):
        res = ""
        inputs = self.inputs
        if not inputs:
            inputs.extend(input().split(" "))
        if n == 0:
            res = inputs[:]
            inputs[:] = []
        while n > len(inputs):
            inputs.extend(input().split(" "))
        if n > 0:
            res = inputs[:n]
            inputs[:n] = []
        return res
InputHandler = InputHandlerObject()

def sqr(n):
    if n == 1:
        return [1]
    if n == 2:
        return [4,3]
    if n % 2:
        return [(n+1)//2, 2] + [1] * (n-2)
    return [(n-2)//2] + [1] * (n-1)

n,m = [int(x) for x in InputHandler.getInput()]

def sum_of_squares(numbers):
    return sum([x**2 for x in numbers])

def find_square_numbers(limit):
    squares = []
    for i in range(1, int(limit**0.5)+1):
        if sum_of_squares(sqr(i)) == i**2:
            squares.append(i**2)
    return squares

limit = max(find_square_numbers(10**16))

if sum_of_squares(sqr(n)) != limit or sum_of_squares(sqr(m)) != limit:
    print("No solution exists.")
    exit()

for i in range(n):
    res = [str(sqr(n)[i]*x) for x in sqr(m)]
    print(" ".join(res))
