    c -= 1
    a -= 1
    b -= 1
    cgr[c][a].append(b)
    cgr[c][b].append(a)
q = int(input())
for i in range(q):
    u, v = (int(x) for x in input().split())
    ans = 0
    for gr in cgr:
        ans += check(gr, u - 1, v - 1)
    print(ans)
