import sys
input = sys.stdin.readline
MOD = 998244353

n = int(input())
info = [list(map(int, input().split())) for i in range(n)]
ans = 0

memo = {} # Count the number of times each item is wanted by other kids
for i in range(n):
    for j in info[i][1:]:
        if j-1 not in memo:
            memo[j-1] = 1
        else:
            memo[j-1] += 1

memo_p = {} # Calculate the probability of each item for each kid
student_p = 1 * pow(n, MOD-2, MOD) # Calculate the probability of choosing any kid
pow_memo = {} # Calculate the probability of choosing any item for a kid
for i in range(n):
    k = info[i][0] # The number of items wanted by the kid
    if k not in pow_memo:
        pow_memo[k] = pow(k, MOD-2, MOD) # Calculate the probability of choosing any item for a kid with k items
    for j in info[i][1:]:
        if j-1 not in memo_p:
            memo_p[j-1] = pow_memo[k]
        else:
            memo_p[j-1] += pow_memo[k]
        memo_p[j-1] %= MOD # Calculate the probability of choosing any item for a kid with k items and considering the number of times each item is wanted by other kids

for i in memo:
    ans += memo[i] * memo_p[i] # Calculate the total number of valid decisions
ans %= MOD # Calculate the final answer as an irreducible fraction
print((ans * student_p * student_p) % MOD) # Print the final answer```

