def solve(index, ops):
    def _solve(index, op):
        t, l, r = op
        if index < l or index > r:
            return index
        if t == 1:
            if index == l:
                return r
            else:
                return index - 1
        else:
            return l + r - index

    for op in ops[::-1]:
        index = _solve(index, op)
    return index

