            for n in range(4):
                dp[i+1][j][n] = max(dp[i+1][j][n], dp[i][j][n])
                dp[i][j+1][n] = max(dp[i][j+1][n], dp[i][j][n])
                if n <= 2:
                    dp[i+1][j][n+1] = max(dp[i+1][j][3], dp[i][j][3] + v_list[i+1][j])
                    dp[i][j+1][n+1] = max(dp[i][j+1][n+1], dp[i][j][n] + v_list[i][j+1])
    return dp[R][C][3]

