#include <bits/stdc++.h>

using namespace std;

ll cubeSum(ll x)
{
	ll sum=0;

	while(x)
{
		ll d=x%10;
		sum+=d;
		x=x/10;
	}

	return sum*sum*sum;
	}


ll dp[5005][5005];

ll recur(vector<ll> &power,ll n,ll r,ll &curr,vector<ll> &vec)
{
	if(r>n)
		return INT_MIN;

	if(n==power.size()-1)
		return 0;

	if(dp[n][r]!=-1)
		return dp[n][r];

	ll val=0;

	val=max(val,recur(power,n+1,r+1,curr,vec));

	val=max(val,power[r]*vec[n]+recur(power,n+1,r,curr,vec));

	return dp[n][r]=val;
	}


void solve()
{
	ll n,s; cin>>n>>s;

	vector<ll> power(n+1); power[0]=s;

	vector<ll> vec(n);

	for(int i=0; i<n; i++)
		cin>>vec[i];

	for(int i=1; i<=n; i++)
	{
		power[i]=power[i-1]+cubeSum(power[i-1]);
		// cout<<power[i] << " ";
	}

	memset(dp,-1,sizeof(dp));

	cout<<recur(power,0,0,s,vec)<<"
";

	}


