def read_int_ary():
  return map(int, stdin.readline().strip().split())

def dfs(graph, start):
  visited, tree, processed, stack = set(), [], set(), [start]
  while stack:
    vertex = stack.pop()
    if vertex not in visited:
      visited.add(vertex)
      stack.extend(graph[vertex] - visited)
    if not vertex in processed:
      tree.append(vertex)
    processed.add(vertex)
  return tree

