')]

    @lru_cache(None)
    def fact(n):
        ans = 1
        if n == 0:
            return 1
        for i in range(1, n + 1):
            ans *= i
        return ans

    def ncr(n, r):
        return fact(n) / (fact(r) * fact(n - r))

