```python
MOD = 998244353
def pow(base , exp):
    if exp == -1:
        return pow(base , MOD - 2)
    res = 1
    base %= MOD
    while exp > 0:
        if exp % 2:
            res = (res * base) % MOD
        exp //= 2
        base = (base * base) % MOD
    res %= MOD
    return res
def main():
