        ANS+=A[0]//(k+1)
        for i in range(1,len(A)):
            ANS+=max(0,A[i]-k)//(k+1)
    elif S[-1]=="0":
        ANS+=A[-1]//(k+1)
        for i in range(len(A)-1):
            ANS+=max(0,A[i]-k)//(k+1)
    else:
        for i in range(len(A)):
            ANS+=max(0,A[i]-k)//(k+1)
    print(ANS)
```

