for _ in range(int(input())):
	# Create a copy of the input Sudoku solution
	sudoku = input().split()
	# Modify at most 9 elements to create an anti-Sudoku
	modified = sudoku.copy()
	num_changes = 0
	while num_changes < 9:
		# Find a row, column, or block that contains less than two equal elements
		for i in range(9):
			row = modified[i]
			if len(set(row)) < 2:
				# Find a number in the row that can be replaced
				for j in range(9):
					if modified[i][j] != row[j]:
						# Replace the number with a different number
						modified[i][j] = str(row[j] + 1 if row[j] < 8 else 1)
						num_changes += 1
				break
			break
		for j in range(9):
			col = [modified[i][j] for i in range(9)]
			if len(set(col)) < 2:
				# Find a number in the column that can be replaced
				for i in range(9):
					if modified[i][j] != col[i]:
						# Replace the number with a different number
						modified[i][j] = str(col[i] + 1 if col[i] < 8 else 1)
						num_changes += 1
				break
			break
		for i in range(0, 9, 3):
			for j in range(0, 9, 3):
				block = [modified[i+x][j+y] for x in range(3) for y in range(3)]
				if len(set(block)) < 2:
					# Find a number in the block that can be replaced
					for x in range(3):
						for y in range(3):
							if modified[i+x][j+y] != block[x][y]:
								# Replace the number with a different number
								modified[i+x][j+y] = str(block[x][y] + 1 if block[x][y] < 8 else 1)
								num_changes += 1
							break
				break
			break
		print(' '.join(modified))

