                flg_down = True
            if j > 0:
                flg_left = False if s[i][j-1] == '#' else True
            else:
                flg_left = True
            if j < w - 1:
                flg_right = False if s[i][j+1] == '#' else True
            else:
                flg_right = True
            # 1つでも孤立でないフラグがあれば孤立でないのでFalse、全部孤立の時True
            if flg_up & flg_down & flg_left & flg_right:
                ans = 'No'
                break

print(ans)
