def min_squares(canvas, length, width):
    def find_top():
        for i in range(length):
            for j in range(width):
                if canvas[i][j] == 'B':
                    return i
    def find_left():
        for j in range(width):
            for i in range(length):
                if canvas[i][j] == 'B':
                    return j
    def find_bottom():
        for i in reversed(list(range(length))):
            for j in range(width):
                if canvas[i][j] == 'B':
                    return i
    def find_right():
        for j in reversed(list(range(width))):
            for i in range(length):
                if canvas[i][j] == 'B':
                    return j
    t = find_top()
    if t == -1:
        return 1
    l = find_left()
    b = find_bottom()
    r = find_right()
    ...
