def factorial_1(n: int):
    for i in range(2, n+1):
        if i > n**0.5:
            return n
        elif n % i == 0:
            return i

def factorial_2(n: int):
    res = dict()
    while n > 1:
        f_now = factorial_1(n)
        n //= f_now
        res[f_now] = res.get(f_now, 0) + 1
    return res

