def ok(p):
    rs = 0
    if k >= p:
        rs += p * (p + 1) // 2
        rs += (k - p)
    else:
        rs += p * (p + 1) // 2
        f = p - k
        rs -= f * (f + 1) // 2
    if (p - 1) <= n - k:
        rs += p * (p - 1) // 2
        rs += n - k - p + 1
    else:
        rs += p * (p - 1) // 2
        f = (p - 1) - (n - k)
        rs -= f * (f + 1) // 2
    return rs <= m

