import sys
import math as m

def sort(a):
    mid = m.ceil(len(a)/2)
    if len(a) == 1:
        return a
    else:
        al = sort(a[:mid])
        ar = sort(a[mid:])
        i = 0
        j = 0
        sa = []
        c = []
        while i < len(al) or j < len(ar):
            if i == len(al):
                sa.append(ar[j])
                j += 1
            elif j == len(ar):
                sa.append(al[i])
                i += 1
            elif al[i]>ar[j]:
                sa.append(ar[j])
                j += 1
            else:
                sa.append(al[i])
                i += 1
        return sa

