```python
def bgcd(a, b):
    d = 0
    while a % 2 == 0 and b % 2 == 0:
        a //= 2
        b //= 2
        d += 1
    while a != b:
        if a % 2 == 0:
            a //= 2
        elif b % 2 == 0:
            b //= 2
        else:
            if a > b:
                a = (a - b) // 2
            else:
                b = (b - a) // 2
    g = a * 2**d
    return g

def f(x, y):
    if y == 0:
        return 0
    else:
        return 1 + f(x, y - bgcd(x, y))

