            maxh = people[i][j]
            S = people[i][j ^ 1]
            for k in range(n):
                if k != i:
                    w, h = people[k]
                    w, h = min(w, h), max(w, h)
                    if w > maxh:
                        S = float('inf')
                        break
                    if h > maxh:
