Q = []
for i, s in enumerate(seg):
    l=None if i  ==0 else i-1
r=None if i+1==len(seg) else i+1
d[i] = [l, r, s[0], s[1]]

    heapq.heappush(Q, (-s[0], i))       

cnt=0
while len(Q) > 0:
    length, idx = heapq.heappop(Q)
    length = -length

    if d[idx][2] != length:
        continue

    l, r, length, val = d[idx] 
d[idx][0]=0
    cnt+=1

    if l is None and r is None:
