class Fraction:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def __sub__(self, a):
        return Fraction(self.x * a.y - a.x * self.y, self.y * a.y)
    def __lt__(self, a):
        return self.x * a.y < self.y * a.x
    def __abs__(self):
        if self.x < 0:
            return Fraction(-self.x, self.y)
        return self
    def __str__(self):
        return str(self.x) + '/' + str(self.y)

