MOD = int(1e9+7)

def mult(l, r):
	return (l*r)%MOD

def fast_exp(b, e):
	if e == 0:
		return 1
	if e%2 == 1:
		return mult(b, fast_exp(b, e-1))
	else:
		b2 = fast_exp(b, e//2)
		return mult(b2, b2)

[n, k] = [int(s) for s in input().split(" ")]
fact = (n+1)*[1]
for i in range(1, n+1):
	fact[i] = mult(i, fact[i-1])

ifact = (n+1)*[1]
ifact[n] = fast_exp(fact[n], MOD-2)
for i in reversed(range(1, n)):
	ifact[i] = mult(i+1, ifact[i+1])

def binom(N, K):
	return mult(mult(fact[N], ifact[K]), ifact[N-K])

def get(i, j):
	X = i*j
	Y = (n-i)*j
	Z = (n-j)*i
	tot = X+Y+Z
	ans = 0
	if (i+j)%2 == 0:
		ans = 1
	else:
		ans = (MOD - 1)
	ans = mult(ans, binom(n, j))
	ans = mult(ans, binom(n, i))
	ans = mult(ans, fast_exp(k, n*n - tot))
	ans = mult(ans, fast_exp(k-1, tot))
	return ans

